const action = msg._req && msg._req.action;
const payload = (msg._req && msg._req.payload) || {};
const IDENT = /^[A-Za-z0-9_.-]{1,64}$/;

function safe(v) { return String(v).replace(/'/g, "''"); }
function badField(name) { msg._result = { ok: false, errors: { fields: { [name]: 'required or invalid' } } }; return [null, msg]; }

// ─── Existing actions (preserved) ──────────────────────────────────────
if (action === 'smart-city.zones.list') {
    msg._sql = `SELECT DISTINCT zone_id FROM "gold"."streetlight_zone_hourly" ORDER BY zone_id`;
    msg._fapShape = 'zones_list'; return [msg, null];
}
if (action === 'smart-city.zones.detail') {
    if (!payload.zone_id || !IDENT.test(payload.zone_id)) return badField('zone_id');
    const z = safe(payload.zone_id);
    msg._sql = `SELECT 'streetlights' AS source, hour AS ts, CAST(avg_dimming_pct AS DOUBLE) AS v1, CAST(total_power_w AS DOUBLE) AS v2 FROM "gold"."streetlight_zone_hourly" WHERE zone_id = '${z}' AND hour >= (SELECT MAX(hour) FROM "gold"."streetlight_zone_hourly") - INTERVAL '24' HOUR UNION ALL SELECT 'traffic' AS source, hour AS ts, CAST(traffic_index AS DOUBLE) AS v1, CAST(0 AS DOUBLE) AS v2 FROM "gold"."traffic_pattern_hourly" WHERE zone_id = '${z}' AND hour >= (SELECT MAX(hour) FROM "gold"."traffic_pattern_hourly") - INTERVAL '24' HOUR ORDER BY ts DESC LIMIT 200`;
    msg._fapShape = 'zone_detail'; msg._zone_id = payload.zone_id; return [msg, null];
}
if (action === 'smart-city.streetlights.list') {
    msg._sql = `SELECT zone_id, MAX(hour) AS hour, AVG(avg_dimming_pct) AS avg_dimming_pct, AVG(total_power_w) AS total_power_w, MAX(light_count) AS light_count FROM "gold"."streetlight_zone_hourly" WHERE hour >= (SELECT MAX(hour) FROM "gold"."streetlight_zone_hourly") - INTERVAL '24' HOUR GROUP BY zone_id ORDER BY zone_id`;
