    msg._sql = `SELECT zone_id, AVG(traffic_index) AS avg_traffic_index, MAX(traffic_index) AS peak_traffic_index FROM "gold"."traffic_pattern_hourly" WHERE hour >= (SELECT MAX(hour) FROM "gold"."traffic_pattern_hourly") - INTERVAL '24' HOUR GROUP BY zone_id ORDER BY avg_traffic_index DESC`;
    msg._fapShape = 'traffic_summary'; return [msg, null];
}
if (action === 'smart-city.events.recent') {
    msg._sql = `SELECT event_date, zone_id, event_type, event_count, avg_severity, active_count FROM "gold"."event_impact_daily" WHERE event_date >= CAST((SELECT MAX(event_date) FROM "gold"."event_impact_daily") - INTERVAL '7' DAY AS DATE) AND active_count > 0 ORDER BY event_date DESC, zone_id`;
    msg._fapShape = 'events_recent'; return [msg, null];
}

// ─── NEW: streetlights current / history ───────────────────────────────
// gold.streetlight_zone_hourly is keyed by zone_id; the SPA's "light_id"
// is treated as zone_id (the gold layer doesn't carry per-light rows).
if (action === 'smart-city.streetlights.current') {
    if (!payload.light_id || !IDENT.test(payload.light_id)) return badField('light_id');
    const z = safe(payload.light_id);
    msg._sql = `SELECT hour, zone_id, avg_dimming_pct, total_power_w, light_count FROM "gold"."streetlight_zone_hourly" WHERE zone_id = '${z}' ORDER BY hour DESC LIMIT 1`;
    msg._fapShape = 'streetlight_current'; msg._light_id = payload.light_id; return [msg, null];
}
if (action === 'smart-city.streetlights.history') {
    if (!payload.light_id || !IDENT.test(payload.light_id)) return badField('light_id');
    const z = safe(payload.light_id);
    msg._sql = `SELECT hour, zone_id, avg_dimming_pct, total_power_w, light_count FROM "gold"."streetlight_zone_hourly" WHERE zone_id = '${z}' AND hour >= (SELECT MAX(hour) FROM "gold"."streetlight_zone_hourly") - INTERVAL '24' HOUR ORDER BY hour ASC`;
    msg._fapShape = 'streetlight_history'; msg._light_id = payload.light_id; return [msg, null];
}

// ─── NEW: traffic zones / current / history ────────────────────────────
if (action === 'smart-city.traffic.zones') {
    msg._sql = `SELECT DISTINCT zone_id FROM "gold"."traffic_pattern_hourly" ORDER BY zone_id`;
    msg._fapShape = 'traffic_zones'; return [msg, null];
}
if (action === 'smart-city.traffic.current') {
    if (!payload.zone_id || !IDENT.test(payload.zone_id)) return badField('zone_id');
    const z = safe(payload.zone_id);
    msg._sql = `SELECT hour, zone_id, traffic_index FROM "gold"."traffic_pattern_hourly" WHERE zone_id = '${z}' ORDER BY hour DESC LIMIT 1`;
    msg._fapShape = 'traffic_current'; msg._zone_id = payload.zone_id; return [msg, null];
}
if (action === 'smart-city.traffic.history') {
    if (!payload.zone_id || !IDENT.test(payload.zone_id)) return badField('zone_id');
    const z = safe(payload.zone_id);
    msg._sql = `SELECT hour, zone_id, traffic_index FROM "gold"."traffic_pattern_hourly" WHERE zone_id = '${z}' AND hour >= (SELECT MAX(hour) FROM "gold"."traffic_pattern_hourly") - INTERVAL '24' HOUR ORDER BY hour ASC`;
    msg._fapShape = 'traffic_history'; msg._zone_id = payload.zone_id; return [msg, null];
}

// ─── NEW: events zones / current / history ─────────────────────────────
if (action === 'smart-city.events.zones') {
    msg._sql = `SELECT DISTINCT zone_id FROM "gold"."event_impact_daily" ORDER BY zone_id`;
    msg._fapShape = 'events_zones'; return [msg, null];
}
if (action === 'smart-city.events.current') {
    if (!payload.zone_id || !IDENT.test(payload.zone_id)) return badField('zone_id');
    const z = safe(payload.zone_id);
    msg._sql = `SELECT event_date, zone_id, event_type, event_count, avg_severity, active_count FROM "gold"."event_impact_daily" WHERE zone_id = '${z}' ORDER BY event_date DESC LIMIT 1`;
    msg._fapShape = 'event_current'; msg._zone_id = payload.zone_id; return [msg, null];
}
if (action === 'smart-city.events.history') {
    if (!payload.zone_id || !IDENT.test(payload.zone_id)) return badField('zone_id');
    const z = safe(payload.zone_id);
    msg._sql = `SELECT event_date, zone_id, event_type, event_count, avg_severity, active_count FROM "gold"."event_impact_daily" WHERE zone_id = '${z}' AND event_date >= CAST((SELECT MAX(event_date) FROM "gold"."event_impact_daily") - INTERVAL '30' DAY AS DATE) ORDER BY event_date ASC`;
    msg._fapShape = 'event_history'; msg._zone_id = payload.zone_id; return [msg, null];
}

// ─── NEW: city weather current / history ───────────────────────────────
if (action === 'smart-city.weather.current') {
    msg._sql = `SELECT hour, avg_temperature_c, avg_irradiance_w_m2, avg_humidity_pct, avg_wind_speed_ms, avg_cloud_cover_pct FROM "gold"."weather_hourly" ORDER BY hour DESC LIMIT 1`;
    msg._fapShape = 'weather_current'; return [msg, null];
}
if (action === 'smart-city.weather.history') {
    msg._sql = `SELECT hour, avg_temperature_c, avg_irradiance_w_m2, avg_humidity_pct, avg_wind_speed_ms, avg_cloud_cover_pct FROM "gold"."weather_hourly" WHERE hour >= (SELECT MAX(hour) FROM "gold"."weather_hourly") - INTERVAL '24' HOUR ORDER BY hour ASC`;
    msg._fapShape = 'weather_history'; return [msg, null];
}

msg._result = { ok: false, errors: { action: 'smart-city: unknown action: ' + action } };
return [null, msg];

// Trino client for FAP (UIBUILDER §9) path. Reads msg._sql + msg._fapShape;
// produces msg._result for fn_build_response upstream of merge-session-send.
function httpsFetch(urlStr, opts = {}) { return new Promise((resolve, reject) => { let parsed; try { parsed = new urlmod.URL(urlStr); } catch (e) { return reject(new Error('bad URL')); } const lib = parsed.protocol === 'https:' ? https : http; const headers = Object.assign({}, opts.headers || {}); if (opts.body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(opts.body); const req = lib.request({ method: opts.method || 'GET', hostname: parsed.hostname, port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80), path: parsed.pathname + (parsed.search || ''), headers, timeout: opts.timeoutMs || 8000, rejectUnauthorized: opts.rejectUnauthorized !== false }, (res) => { let d = ''; res.on('data', c => d += c); res.on('end', () => resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, json: () => { try { return Promise.resolve(JSON.parse(d)); } catch (e) { return Promise.reject(e); } } })); }); req.on('error', reject); req.on('timeout', () => req.destroy(new Error('timeout'))); if (opts.body) req.write(opts.body); req.end(); }); }
const formEncode = (o) => Object.entries(o).filter(([,v]) => v !== undefined && v !== null && v !== '').map(([k,v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
const T = { tokenUrl: env.get('AI_INSIGHT_TRINO__OIDC_TOKEN_URL'), clientId: env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_ID'), clientSecret: env.get('AI_INSIGHT_TRINO__OIDC_CLIENT_SECRET'), username: env.get('AI_INSIGHT_TRINO__OIDC_USERNAME'), password: env.get('AI_INSIGHT_TRINO__OIDC_PASSWORD'), scope: env.get('AI_INSIGHT_TRINO__OIDC_SCOPE') || 'openid', scheme: env.get('AI_INSIGHT_TRINO__HTTP_SCHEME') || 'https', host: env.get('AI_INSIGHT_TRINO__HOST'), port: env.get('AI_INSIGHT_TRINO__PORT') || 8443, user: env.get('AI_INSIGHT_TRINO__USER') || 'trino', catalog: env.get('AI_INSIGHT_TRINO__CATALOG') || 'fap-iotai-stackable' };
async function runSql(sql) { const tres = await httpsFetch(T.tokenUrl, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: formEncode({ grant_type: 'password', client_id: T.clientId, client_secret: T.clientSecret, username: T.username, password: T.password, scope: T.scope }), rejectUnauthorized: false }); if (!tres.ok) throw new Error('token grant failed: ' + tres.status); const token = (await tres.json()).access_token; const base = `${T.scheme}://${T.host}:${T.port}`; const headers = { 'Authorization': 'Bearer ' + token, 'X-Trino-User': T.user, 'X-Trino-Catalog': T.catalog, 'Content-Type': 'text/plain' }; let res = await httpsFetch(`${base}/v1/statement`, { method: 'POST', headers, body: sql, rejectUnauthorized: false }); if (!res.ok) throw new Error('POST /v1/statement failed: ' + res.status); let body = await res.json(); let columns = body.columns || null; const rows = body.data ? [...body.data] : []; while (body.nextUri) { res = await httpsFetch(body.nextUri, { headers, rejectUnauthorized: false }); if (!res.ok) throw new Error('nextUri failed: ' + res.status); body = await res.json(); if (body.columns) columns = body.columns; if (body.data) rows.push(...body.data); } return { columns, rows }; }

try {
    const { columns, rows } = await runSql(msg._sql);
    const cols = (columns || []).map(c => c.name);
    const objs = rows.map(r => { const o = {}; for (let i = 0; i < cols.length; i++) o[cols[i]] = r[i]; return o; });
    const meta = { source: 'gold', generated_at: new Date().toISOString(), row_count: objs.length };
    function emptyMeta(extra) { return Object.assign({}, meta, { note: 'no rows in window' }, extra || {}); }
    let data;
    switch (msg._fapShape) {
        // Existing shapes
        case 'zones_list':
            data = { zones: objs.map(o => ({ zone_id: o.zone_id })), count: objs.length, metadata: meta };
            break;
        case 'zone_detail':
            data = { zone_id: msg._zone_id, recent_observations: objs, metadata: meta };
            break;
        case 'streetlights_list':
            data = {
                streetlights: objs.map(o => ({
                    light_id: o.zone_id, zone_id: o.zone_id, rated_power_w: 75,
                    dimming_level_pct: Number(o.avg_dimming_pct) || 0,
                    power_w: Number(o.total_power_w) || 0,
                    light_count: Number(o.light_count) || 0,
                    last_hour: o.hour
                })),
                count: objs.length,
                metadata: meta
            };
            break;
        case 'traffic_summary':
            data = { zones: objs, count: objs.length, peak_zone: objs[0] ? objs[0].zone_id : null, metadata: meta };
            break;
        case 'events_recent':
            data = {
                events: objs.map(o => ({
                    zone_id: o.zone_id,
                    timestamp: String(o.event_date),
                    event_type: o.event_type,
                    severity: String(o.avg_severity ?? 'unknown'),
                    active: Number(o.active_count) > 0,
                    count: Number(o.event_count) || 0
                })),
                count: objs.length,
                metadata: meta
            };
            break;
        // NEW shapes (Sim* shapes preserved 1:1 with the SPA's interfaces)
        case 'streetlight_current':
            if (!objs.length) { data = { metadata: emptyMeta({ light_id: msg._light_id }) }; break; }
            data = {
                timestamp: objs[0].hour,
                light_id: msg._light_id,
                zone_id: objs[0].zone_id,
                dimming_level_pct: Number(objs[0].avg_dimming_pct) || 0,
                power_w: Number(objs[0].total_power_w) || 0,
                metadata: meta
            };
            break;
        case 'streetlight_history':
            data = {
                light_id: msg._light_id,
                readings: objs.map(r => ({
                    timestamp: r.hour,
                    zone_id: r.zone_id,
                    dimming_level_pct: Number(r.avg_dimming_pct) || 0,
                    power_w: Number(r.total_power_w) || 0
                })),
                metadata: meta
            };
            break;
        case 'traffic_zones':
            data = { zones: objs.map(o => ({ zone_id: o.zone_id })), count: objs.length, metadata: meta };
            break;
        case 'traffic_current':
            if (!objs.length) { data = { metadata: emptyMeta({ zone_id: msg._zone_id }) }; break; }
            data = {
                timestamp: objs[0].hour,
                zone_id: objs[0].zone_id,
                traffic_index: Number(objs[0].traffic_index) || 0,
                metadata: meta
            };
            break;
        case 'traffic_history':
            data = {
                zone_id: msg._zone_id,
                readings: objs.map(r => ({ timestamp: r.hour, traffic_index: Number(r.traffic_index) || 0 })),
                metadata: meta
            };
            break;
        case 'events_zones':
            data = { zones: objs.map(o => ({ zone_id: o.zone_id })), count: objs.length, metadata: meta };
            break;
        case 'event_current':
            if (!objs.length) { data = { metadata: emptyMeta({ zone_id: msg._zone_id }) }; break; }
            data = {
                timestamp: String(objs[0].event_date),
                zone_id: objs[0].zone_id,
                event_type: objs[0].event_type,
                severity: String(objs[0].avg_severity ?? 'unknown'),
                active: Number(objs[0].active_count) > 0,
                metadata: meta
            };
            break;
        case 'event_history':
            data = {
                zone_id: msg._zone_id,
                readings: objs.map(r => ({
                    timestamp: String(r.event_date),
                    event_type: r.event_type,
                    severity: String(r.avg_severity ?? 'unknown'),
                    active: Number(r.active_count) > 0
                })),
                metadata: meta
            };
            break;
        case 'weather_current': {
            if (!objs.length) { data = { metadata: emptyMeta() }; break; }
            // gold.weather_hourly has no fog/visibility column; derive from cloud cover.
            const r = objs[0];
            const cc = Number(r.avg_cloud_cover_pct) || 0;
            const fog = cc / 100 * 0.6;
            data = {
                timestamp: r.hour,
                fog_index: Math.round(fog * 100) / 100,
                visibility: Math.round(10000 * (1 - fog * 0.8)),
                sunrise_time: null,
                sunset_time: null,
                metadata: Object.assign({ note: 'fog/visibility derived from gold.weather_hourly cloud cover; gold has no per-station sunrise/sunset' }, meta)
            };
            break;
        }
        case 'weather_history':
            data = {
                readings: objs.map(rr => {
                    const cc = Number(rr.avg_cloud_cover_pct) || 0;
                    const fog = cc / 100 * 0.6;
                    return {
                        timestamp: rr.hour,
                        fog_index: Math.round(fog * 100) / 100,
                        visibility: Math.round(10000 * (1 - fog * 0.8)),
                        sunrise_time: null,
                        sunset_time: null
                    };
                }),
                metadata: meta
            };
            break;
        default:
            data = { rows: objs, metadata: meta };
    }
    msg._result = { ok: true, data };
} catch (e) {
    node.warn('smart-city Trino query failed (FAP): ' + String(e.message || e));
    msg._result = { ok: false, errors: { integration: { service: 'trino', message: 'gold layer query failed' } } };
}
return msg;
